import * as THREE from 'three';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import {RoomEnvironment} from 'three/addons/environments/RoomEnvironment.js';

// Structural detail is independent of WCM time: these are verified static predictions.
export async function createStructureExplorer(){
 const style=document.createElement('link');style.rel='stylesheet';style.href='/protein-structure.css';document.head.append(style);
 const panel=document.createElement('section');panel.id='protein-structure-card';panel.hidden=true;
 panel.innerHTML='<span class="eyebrow">MOLECULAR STRUCTURE</span><strong id="protein-structure-name">选择一种蛋白质</strong><p id="protein-structure-status"></p><button id="protein-structure-open" class="secondary-btn" disabled>查看三维结构</button><button id="protein-library-open" class="structure-library-link">浏览已验证结构库 ↗</button>';
 document.querySelector('#subtype-panel').before(panel);
 const dialog=document.createElement('dialog');dialog.id='protein-structure-dialog';dialog.innerHTML=`<div class="dialog-header"><span class="eyebrow">JCVI-SYN3A / STRUCTURAL ATLAS</span><button type="button" class="icon-btn" id="protein-close" aria-label="关闭">×</button></div><div class="structure-heading"><div><h2 id="protein-title"></h2><p id="protein-product"></p></div><span class="structure-badge">AlphaFold · 预测结构</span></div><div class="structure-tools"><label>已验证蛋白质<select id="protein-picker"></select></label><label>表现方式<select id="protein-style"><option value="backbone">主链曲线</option><option value="atoms">原子空间填充</option></select></label><label>配色<select id="protein-color"><option value="palette">观察台色系</option><option value="confidence">预测可信度</option></select></label><button type="button" id="protein-reset" class="secondary-btn">恢复视角</button></div><div id="protein-canvas"><div id="protein-loading" role="status">加载结构</div><div class="structure-canvas-caption"><span>拖动旋转 · 滚动缩放</span><span>静态结构 · Å</span></div></div><div id="protein-color-key"></div><div class="structure-facts"><div><small>序列一致性 / 覆盖率</small><strong>100% / 100%</strong></div><div><small>平均预测可信度</small><strong id="protein-confidence"></strong></div><div><small>氨基酸 / 原子</small><strong id="protein-size"></strong></div></div><p id="protein-provenance"></p><p class="structure-boundary">预测结构不是实验测定，也不是当前时刻的分子构象。总览保留 WCM 格点位置；此处展示独立的单链结构。低可信度区域请谨慎解释。</p><div class="reference-links"><a id="protein-source" target="_blank" rel="noreferrer">AlphaFold DB ↗</a><a id="protein-download" target="_blank" rel="noreferrer">原始 PDB ↗</a></div><small class="structure-credit">Google DeepMind · EMBL-EBI / CC BY 4.0</small>`;document.body.append(dialog);
 const $=s=>dialog.querySelector(s);let catalogue,selected=null,entry=null,data=null,request=0,renderer,scene,camera,controls,group,homeDistance=100,dirty=true;
 try{const r=await fetch('/assets/structures/catalog.json');if(!r.ok)throw Error();catalogue=await r.json();}catch{document.querySelector('#protein-structure-status').textContent='结构目录加载失败，请刷新重试';document.querySelector('#protein-library-open').disabled=true;return {selection(id){panel.hidden=id!=='protein';}};}
 const available=catalogue.entries.filter(e=>e.available),byLocus=new Map(catalogue.entries.map(e=>[e.locus.split('_').at(-1),e]));
 for(const e of available){const option=document.createElement('option');option.value=e.locus;option.textContent=`${e.gene||e.locus} · ${e.locus.split('_').at(-1)} · ${e.product}`;$('#protein-picker').append(option);}
 function selection(component,species){panel.hidden=component!=='protein';const locus=species?.name.match(/_(\d{4})(?:_|$)/)?.[1];selected=byLocus.get(locus)||null;document.querySelector('#protein-structure-name').textContent=selected?`${selected.gene||selected.locus} · ${species.name}`:'选择一种蛋白质';document.querySelector('#protein-structure-status').textContent=selected?.available?'全长序列一致 · AlphaFold 预测':selected?'当前结构库尚未收录此蛋白质':'在下方列表选择蛋白质，查看可用结构。';document.querySelector('#protein-structure-open').disabled=!selected?.available;document.querySelector('#protein-library-open').textContent=`浏览已验证结构库 ↗ ${available.length} / ${catalogue.total}`;}
 function initialize(){if(renderer)return;const host=$('#protein-canvas');renderer=new THREE.WebGLRenderer({alpha:true,antialias:true,preserveDrawingBuffer:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;host.prepend(renderer.domElement);scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(32,1,.1,20000);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.minDistance=5;controls.maxDistance=4000;group=new THREE.Group();scene.add(group);const pmrem=new THREE.PMREMGenerator(renderer),room=new RoomEnvironment();scene.environment=pmrem.fromScene(room,.04).texture;room.dispose();pmrem.dispose();scene.add(new THREE.HemisphereLight('#fff9ef','#91849a',1.5));const key=new THREE.DirectionalLight('#fff3dc',3);key.position.set(-50,80,100);scene.add(key);const fill=new THREE.DirectionalLight('#d4c7eb',1.3);fill.position.set(70,10,-30);scene.add(fill);function resize(){if(!dialog.open)return;const w=host.clientWidth,h=host.clientHeight;camera.aspect=w/h;camera.updateProjectionMatrix();renderer.setSize(w,h);dirty=true;}new ResizeObserver(resize).observe(host);resize();function tick(){requestAnimationFrame(tick);if(dialog.open){const moved=controls.update();if(dirty||moved){renderer.render(scene,camera);dirty=false;}}}tick();}
 const confidenceColor=p=>p>=90?'#83a194':p>=70?'#c6a158':p>=50?'#c28f99':'#9279a6';
 const atomColors={C:'#c6a158',N:'#9279a6',O:'#c28f99',S:'#83a194',P:'#83a194',H:'#e4d7c2'};
 const atomRadii={C:1.7,N:1.55,O:1.52,S:1.8,P:1.8,H:1.2};
 function draw(resetView=false){if(!data)return;dirty=true;for(const child of [...group.children]){group.remove(child);child.geometry.dispose();child.material.dispose();}const confidence=$('#protein-color').value==='confidence',atoms=$('#protein-style').value==='atoms',mat=()=>new THREE.MeshStandardMaterial({color:'#ffffff',roughness:.34,metalness:.05,envMapIntensity:.75,vertexColors:true});
  if(atoms){const geometry=new THREE.IcosahedronGeometry(1,2),material=mat();material.vertexColors=false;const mesh=new THREE.InstancedMesh(geometry,material,data.atoms.length),temp=new THREE.Object3D();for(let i=0;i<data.atoms.length;i++){const a=data.atoms[i];temp.position.fromArray(a.xyz);temp.scale.setScalar(atomRadii[a.element]||1.7);temp.updateMatrix();mesh.setMatrixAt(i,temp.matrix);mesh.setColorAt(i,new THREE.Color(confidence?confidenceColor(a.plddt):atomColors[a.element]||'#b1a1b8'));}group.add(mesh);
  }else{const chains=[];let current=[];for(const a of data.backbone){const previous=current.at(-1);if(previous&&(a.chain!==previous.chain||a.residue!==previous.residue+1||new THREE.Vector3(...a.xyz).distanceTo(new THREE.Vector3(...previous.xyz))>4.8)){chains.push(current);current=[];}current.push(a);}if(current.length)chains.push(current);for(const chain of chains){if(chain.length<2)continue;const segments=(chain.length-1)*5,geometry=new THREE.TubeGeometry(new THREE.CatmullRomCurve3(chain.map(a=>new THREE.Vector3(...a.xyz)),false,'centripetal'),segments,.65,8,false),colors=new Float32Array(geometry.attributes.position.count*3);for(let i=0;i<colors.length/3;i++){const residue=chain[Math.min(chain.length-1,Math.round(Math.floor(i/9)/segments*(chain.length-1)))];new THREE.Color(confidence?confidenceColor(residue.plddt):'#b89b65').toArray(colors,i*3);}geometry.setAttribute('color',new THREE.BufferAttribute(colors,3));group.add(new THREE.Mesh(geometry,mat()));}}
  group.position.set(0,0,0);const box=new THREE.Box3().setFromObject(group),center=box.getCenter(new THREE.Vector3());group.position.copy(center).multiplyScalar(-1);homeDistance=Math.max(25,box.getSize(new THREE.Vector3()).length()*1.8);if(resetView)reset();$('#protein-color-key').textContent=confidence?'pLDDT：≥90 鼠尾草绿 · 70–90 暖金 · 50–70 玫瑰灰 · <50 灰紫':atoms?'碳：暖金 · 氮：灰紫 · 氧：玫瑰灰 · 硫 / 磷：鼠尾草绿':'主链曲线经过 Cα 坐标；曲面为平滑表现。';
 }
 function reset(){dirty=true;camera.position.set(homeDistance*.22,homeDistance*.12,homeDistance);controls.target.set(0,0,0);controls.update();}
 async function open(e){if(!e?.available)return;const token=++request;entry=e;data=null;if(!dialog.open)dialog.showModal();initialize();for(const o of group.children)o.visible=false;$('#protein-loading').hidden=false;$('#protein-loading').textContent='加载结构';$('#protein-picker').value=e.locus;$('#protein-title').textContent=e.gene||e.locus;$('#protein-product').textContent=e.product;$('#protein-confidence').textContent=e.mean_plddt.toFixed(1)+' / 100';$('#protein-size').textContent=e.length+' / —';$('#protein-provenance').textContent=`${e.locus} · ${e.protein_id} · ${e.model} v${e.version}\n来源物种：${e.source_organism}。与本模型蛋白质全长序列完全一致。`;$('#protein-source').href=e.source_url;$('#protein-download').href=e.pdb_url;try{const r=await fetch(e.asset);if(!r.ok)throw Error();const next=await r.json();if(token!==request)return;data=next;$('#protein-size').textContent=e.length+' / '+data.atoms.length.toLocaleString();draw(true);$('#protein-loading').hidden=true;}catch{if(token===request)$('#protein-loading').textContent='结构加载失败，请重新选择';}}
 document.querySelector('#protein-structure-open').onclick=()=>open(selected);document.querySelector('#protein-library-open').onclick=()=>open(selected?.available?selected:available.find(e=>e.gene==='fbaA')||available[0]);$('#protein-picker').onchange=()=>open(available.find(e=>e.locus===$('#protein-picker').value));$('#protein-style').onchange=$('#protein-color').onchange=()=>draw();$('#protein-reset').onclick=()=>{if(data)reset();};$('#protein-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close();}});
 return {selection,hasStructure(name){return byLocus.get(name.match(/_(\d{4})(?:_|$)/)?.[1])?.available||false;},debug(){return {locus:entry?.locus,atoms:data?.atoms.length,available:available.length,loaded:!!data};}};
}
